from pathlib import Path

p = Path('app/frontend/src/App.jsx')
s = p.read_text()
old = "const visibleReq=requests.filter(x=>x.vendor===profile.display_name&&x.status==='PENDING_VENDOR'&&`${x.vendor||''} ${x.project_location||''} ${x.warehouse||''} ${x.service_type||''}`.toLowerCase().includes(search.toLowerCase()))"
new = "const visibleReq=requests.filter(x=>x.vendor===profile.display_name&&x.status==='PENDING_VENDOR'&&`${x.vendor||''} ${x.project_location||''} ${x.warehouse||''} ${x.service_type||''}`.toLowerCase().includes(search.toLowerCase()))\n const vendorReceivedRequests=requests.filter(x=>x.vendor===profile.display_name&&x.status==='VENDOR_RECEIVED'&&`${x.vendor||''} ${x.project_location||''} ${x.warehouse||''} ${x.service_type||''}`.toLowerCase().includes(search.toLowerCase()))"
if old not in s:
    raise SystemExit('visibleReq target not found')
s = s.replace(old, new, 1)
old2 = "if(active==='Pending for Action'&&role===ROLES.VENDOR)return <VendorPendingRequests requests={visibleReq} selectedRequest={selectedRequest} setSelectedRequest={setSelectedRequest} onSubmit={raiseInvoice}/>;"
new2 = "if(active==='Pending for Action'&&role===ROLES.VENDOR)return <VendorPendingRequests requests={visibleReq} selectedRequest={selectedRequest} setSelectedRequest={setSelectedRequest} onSubmit={raiseInvoice} token={token}/>;if(active==='Received & Under Process'&&role===ROLES.VENDOR)return <VendorReceivedRequests requests={vendorReceivedRequests} selectedRequest={selectedRequest} setSelectedRequest={setSelectedRequest} onSubmit={raiseInvoice} token={token}/>;"
if old2 not in s:
    raise SystemExit('content target not found')
s = s.replace(old2, new2, 1)
start = s.index('function VendorPendingRequests(')
end = s.index('\nfunction WarehouseSubmittedRequests(', start)
replacement = '''function VendorPendingRequests({requests,selectedRequest,setSelectedRequest,onSubmit,token}){const[r,setR]=useState(null);const[viewed,setViewed]=useState({});const[busy,setBusy]=useState(false);const[error,setError]=useState('');const openDoc=async req=>{try{const docs=await selectRows('document_records',`&request_id=eq.${req.id}`);if(!docs.length){alert('No Warehouse document found.');return false}let opened=false;for(const d of docs){const blob=await readRDFile(d.storage_path);if(!blob)continue;const url=URL.createObjectURL(blob);const w=window.open(url,'_blank','noopener,noreferrer');if(w){opened=true;w.addEventListener('load',()=>w.print())}}if(opened)setViewed(v=>({...v,[req.id]:true}));return opened}catch(e){alert(e.message);return false}};const accept=async req=>{if(!viewed[req.id]){setError('View / Download / Print the Warehouse document first.');return}try{setBusy(true);setError('');await updateRows('bill_requests',`id=eq.${req.id}`,{status:'VENDOR_RECEIVED',vendor_received_at:new Date().toISOString(),vendor_received_by:req.vendor},token);setR(req);setSelectedRequest(req)}catch(e){setError(e.message||'Unable to accept Warehouse submission.')}finally{setBusy(false)}};if(r)return <VendorInvoiceForm request={r} onSubmit={onSubmit} onBack={()=>{setR(null);setSelectedRequest(null)}} token={token}/>;return <section className="panel"><div className="panel-heading"><div><h2>Vendor — Pending for Action</h2><p>{requests.length} record(s)</p></div></div><div className="table-wrap"><table><thead><tr><th>Company</th><th>Warehouse</th><th>Project / Location</th><th>Vendor</th><th>Contract Type</th><th>Service Type</th><th>Sub-category</th><th>Submitted</th><th>Action</th></tr></thead><tbody>{requests.map(x=><tr key={x.id}><td>{x.company||x.organization}</td><td>{x.warehouse}</td><td>{x.project_location}</td><td>{x.vendor}</td><td>{x.contract_type}</td><td>{x.service_type}</td><td>{x.sub_service}</td><td>{x.created_at?new Date(x.created_at).toLocaleString('en-IN'):''}</td><td><button className="link-btn" onClick={()=>openDoc(x)}>View / Download / Print</button><button className="primary" disabled={!viewed[x.id]||busy} onClick={()=>accept(x)}>{busy?'Accepting…':'Accept'}</button></td></tr>)}</tbody></table>{error&&<div className="notice error">{error}</div>}{!requests.length&&<div className="empty-state">No Warehouse submissions pending for this Vendor.</div>}</div></section>}

function VendorReceivedRequests({requests,selectedRequest,setSelectedRequest,onSubmit,token}){const[r,setR]=useState(null);if(r)return <VendorInvoiceForm request={r} onSubmit={onSubmit} onBack={()=>{setR(null);setSelectedRequest(null)}} token={token}/>;return <section className="panel"><div className="panel-heading"><div><h2>Vendor — Received & Under Process</h2><p>{requests.length} record(s)</p></div></div><div className="table-wrap"><table><thead><tr><th>Company</th><th>Warehouse</th><th>Project / Location</th><th>Vendor</th><th>Contract Type</th><th>Service Type</th><th>Sub-category</th><th>Received At</th><th>Action</th></tr></thead><tbody>{requests.map(x=><tr key={x.id}><td>{x.company||x.organization}</td><td>{x.warehouse}</td><td>{x.project_location}</td><td>{x.vendor}</td><td>{x.contract_type}</td><td>{x.service_type}</td><td>{x.sub_service}</td><td>{x.vendor_received_at?new Date(x.vendor_received_at).toLocaleString('en-IN'):''}</td><td><button className="primary" onClick={()=>setR(x)}>Upload Invoice & Docs</button></td></tr>)}</tbody></table>{!requests.length&&<div className="empty-state">No received Warehouse submissions under process.</div>}</div></section>}

function VendorInvoiceForm({request,onSubmit,onBack,token}){const[invNo,setInvNo]=useState('');const[invMonth,setInvMonth]=useState('');const[invDate,setInvDate]=useState('');const[taxable,setTaxable]=useState('');const[files,setFiles]=useState([]);const[invoiceFile,setInvoiceFile]=useState(null);const[remarks,setRemarks]=useState('');const[error,setError]=useState('');const[busy,setBusy]=useState(false);const submit=async e=>{e.preventDefault();if(!invNo.trim()||!invMonth||!invDate||!invoiceFile||!files.length||!taxable){setError('Complete Invoice Number, Invoice Month, Invoice Date, Invoice PDF, Supporting Documents, Taxable Amount and Remarks before Submit.');return}if(!remarks.trim()){setError('Remarks are mandatory before Submit.');return}if(invoiceFile.type!=='application/pdf'&&!invoiceFile.name.toLowerCase().endsWith('.pdf')){setError('Invoice file must be PDF.');return}try{setBusy(true);setError('');const t=Number(taxable);const gst=Math.round(t*0.18*100)/100;await onSubmit(request,{organization:request.organization,company:request.company||request.organization,warehouse:request.warehouse,project_location:request.project_location,vendor:request.vendor,contract_type:request.contract_type,service_type:request.service_type,sub_category:request.sub_service||request.sub_category,inv_no:invNo.trim(),invoice_month:invMonth,invoice_date:invDate,taxable_amt:t,gst_amt:gst,amt_incl_gst:t+gst,documents:[{type:'Invoice',file:invoiceFile},...files.map(file=>({type:'Supporting Document',file}))],remarks:remarks.trim()});}catch(e){setError(e.message||'Unable to submit invoice.')}finally{setBusy(false)}};return <section className="panel form-panel"><div className="panel-heading"><div><h2>Vendor — Invoice & Supporting Docs</h2><p>Accepted from Warehouse — upload only Vendor invoice/documents</p></div><button onClick={onBack}>Back</button></div><div className="table-wrap"><table className="p2-horizontal-table"><tbody><tr><th>Company</th><td><input value={request.company||request.organization} disabled/></td><th>Warehouse</th><td><input value={request.warehouse} disabled/></td><th>Project / Location</th><td><input value={request.project_location} disabled/></td></tr><tr><th>Vendor</th><td><input value={request.vendor} disabled/></td><th>Contract Type</th><td><input value={request.contract_type} disabled/></td><th>Service Type</th><td><input value={request.service_type} disabled/></td></tr><tr><th>Sub-category</th><td><input value={request.sub_service||request.sub_category||''} disabled/></td><th>WH Remarks</th><td colSpan="3"><input value={request.remarks||''} disabled/></td></tr><tr><th>Invoice Number</th><td><input value={invNo} onChange={e=>setInvNo(e.target.value)} required/></td><th>Invoice Month</th><td><input type="month" value={invMonth} onChange={e=>setInvMonth(e.target.value)} required/></td><th>Invoice Date</th><td><input type="date" value={invDate} onChange={e=>setInvDate(e.target.value)} required/></td></tr><tr><th>Taxable Amount</th><td><input type="number" min="0" step="0.01" value={taxable} onChange={e=>setTaxable(e.target.value)} required/></td><th>Invoice PDF</th><td><input type="file" accept="application/pdf,.pdf" onChange={e=>setInvoiceFile(e.target.files?.[0]||null)} required/></td><th>Supporting Documents</th><td><input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx,.csv" onChange={e=>setFiles(Array.from(e.target.files||[]))} required/></td></tr></tbody></table></div><label>Remarks<textarea value={remarks} onChange={e=>setRemarks(e.target.value)} placeholder="Enter remarks" required/></label><button className="primary" disabled={busy}>{busy?'Submitting…':'Submit to Warehouse'}</button>{error&&<div className="notice error">{error}</div>}</section>}
'''
s = s[:start] + replacement + s[end:]
p.write_text(s)
